WITH profile AS (SELECT profile, CAST(MIN(mp.ts_created) AS DATE) AS dt_created FROM datalake_hub_services_clean.member_profile_aud AS mp GROUP BY 1) SELECT DISTINCT XXHASH64(profile) AS id_profile, profile, dt_created, STRUCT(year AS year) AS year, STRUCT(month AS month) AS month, STRUCT(day AS day) AS day FROM profile WHERE dt_created = MAKE_DATE(STRUCT(year AS year), STRUCT(month AS month), STRUCT(day AS day))